    if 'Limitations' in page and i <= 10:
        # Check if Conclusion is on this page too
        has_conclusion = 'Conclusion' in page
        # Find the position of Limitations relative to page
        lines = page.split('\n')
        for j, line in enumerate(lines):
            if 'Limitations' in line and 'section' not in line.lower() and j < 20:
                print(f'Page {i}: Limitations found at relative line {j}/{len(lines)}')
                break
        if has_conclusion:
            for j, line in enumerate(lines):
                if 'Conclusion' in line and 'section' not in line.lower():
                    print(f'Page {i}: Conclusion found at relative line {j}/{len(lines)}')
                    break
